// Package i18n formats the user-facing messages of the server from the shared ICU
// MessageFormat catalogs in locales/ (ADR-0009).
//
// A Bundle compiles every message of every locale once, so a broken catalog fails at
// startup and in tests. Resolve picks a locale (user setting, then Accept-Language, then
// the instance default, then en), and a Localizer formats messages through typed
// accessors generated by tools/i18n into messages_gen.go, e.g.
//
//	l := bundle.Localizer(bundle.Resolve(i18n.Preferences{AcceptLanguage: r.Header.Get("Accept-Language")}))
//	msg := l.ServerErrorsNotFound()
//
// The package is a leaf library: it imports only the standard library, the catalogs, and
// the MessageFormat engine, so the application and interface layers may both use it.
package i18n

import (
	"encoding/json"
	"fmt"
	"io/fs"
	"path"
	"slices"
	"strings"

	"github.com/best-friends/my/locales"
)

// entry is one catalog message in the FormatJS JSON shape.
type entry struct {
	DefaultMessage string `json:"defaultMessage"`
	Description    string `json:"description,omitempty"`
}

// Option configures a Bundle.
type Option func(*options)

type options struct{ pseudo bool }

// WithPseudoLocales makes the pseudo-locales en-XA and ar-XB selectable. They are meant
// for development and end-to-end tests and are excluded by default.
func WithPseudoLocales() Option { return func(o *options) { o.pseudo = true } }

// Bundle holds the compiled messages of every locale. It is safe for concurrent use.
type Bundle struct {
	messages map[string]map[string]compiledMessage // locale -> "namespace:key" -> message
	locales  []string
}

// Load compiles the catalogs embedded from locales/.
func Load(opts ...Option) (*Bundle, error) { return NewBundle(locales.FS, opts...) }

// NewBundle compiles every <locale>/<namespace>.json catalog in fsys.
func NewBundle(fsys fs.FS, opts ...Option) (*Bundle, error) {
	var o options
	for _, opt := range opts {
		opt(&o)
	}
	files, err := fs.Glob(fsys, "*/*.json")
	if err != nil {
		return nil, err
	}
	b := &Bundle{messages: map[string]map[string]compiledMessage{}}
	compilers := map[string]compiler{}
	for _, file := range files {
		locale, name := path.Split(file)
		locale = strings.TrimSuffix(locale, "/")
		if Canonicalize(locale) != locale {
			return nil, fmt.Errorf("i18n: %s: directory %q is not a canonical BCP 47 tag", file, locale)
		}
		if isPseudo(locale) && !o.pseudo {
			continue
		}
		data, err := fs.ReadFile(fsys, file)
		if err != nil {
			return nil, err
		}
		var catalog map[string]entry
		if err := json.Unmarshal(data, &catalog); err != nil {
			return nil, fmt.Errorf("i18n: %s: %w", file, err)
		}
		c, ok := compilers[locale]
		if !ok {
			if c, err = newCompiler(formattingLocale(locale)); err != nil {
				return nil, fmt.Errorf("i18n: %s: %w", file, err)
			}
			compilers[locale] = c
			b.messages[locale] = map[string]compiledMessage{}
		}
		ns := strings.TrimSuffix(name, ".json")
		for key, e := range catalog {
			m, err := c.compile(e.DefaultMessage)
			if err != nil {
				return nil, fmt.Errorf("i18n: %s %q: %w", file, key, err)
			}
			b.messages[locale][ns+":"+key] = m
		}
	}
	if _, ok := b.messages[SourceLocale]; !ok {
		return nil, fmt.Errorf("i18n: no catalog for the source locale %q", SourceLocale)
	}
	for l := range b.messages {
		b.locales = append(b.locales, l)
	}
	slices.Sort(b.locales)
	return b, nil
}

// Locales returns the locales that have a catalog, sorted.
func (b *Bundle) Locales() []string { return slices.Clone(b.locales) }

// Preferences are the inputs to locale resolution, in priority order (ADR-0009 §2).
type Preferences struct {
	User            string // the user's saved locale, if any
	AcceptLanguage  string // the request's Accept-Language header, if any
	InstanceDefault string // the instance's configured default locale
}

// Resolve returns the first locale with a catalog among the user setting, the
// Accept-Language tags, and the instance default, matching each through its fallback
// chain (ja-JP matches ja). It returns SourceLocale when nothing matches.
func (b *Bundle) Resolve(p Preferences) string {
	candidates := append([]string{p.User}, ParseAcceptLanguage(p.AcceptLanguage)...)
	candidates = append(candidates, p.InstanceDefault)
	for _, c := range candidates {
		if c = Canonicalize(c); c == "" {
			continue
		}
		for _, l := range FallbackChain(c) {
			// Every chain ends with en; only an explicit en request should stop the search there.
			if l == SourceLocale && c != SourceLocale && !strings.HasPrefix(c, SourceLocale+"-") {
				break
			}
			if _, ok := b.messages[l]; ok {
				return l
			}
		}
	}
	return SourceLocale
}

// Localizer formats messages for one locale. Use the generated accessor methods.
type Localizer struct {
	b      *Bundle
	locale string
	chain  []string
}

// Localizer returns a Localizer for locale, normally a result of Resolve. Messages missing
// from locale are looked up along its fallback chain.
func (b *Bundle) Localizer(locale string) *Localizer {
	locale = Canonicalize(locale)
	if locale == "" {
		locale = SourceLocale
	}
	return &Localizer{b: b, locale: locale, chain: FallbackChain(locale)}
}

// Locale returns the locale the Localizer was created for.
func (l *Localizer) Locale() string { return l.locale }

// Direction returns "rtl" or "ltr" for the Localizer's locale.
func (l *Localizer) Direction() string { return Direction(l.locale) }

// format renders the message id ("namespace:key") with args, falling back along the
// locale chain when a locale lacks the message or cannot format it. It returns id when
// no locale can, which the generated accessors and catalog checks make unreachable.
func (l *Localizer) format(id string, args map[string]any) string {
	for _, locale := range l.chain {
		m, ok := l.b.messages[locale][id]
		if !ok {
			continue
		}
		if out, err := m.format(args); err == nil {
			return out
		}
	}
	return id
}
